create extension if not exists "uuid-ossp";
create table if not exists public.markets (id uuid primary key default uuid_generate_v4(), name text not null, created_at timestamptz default now());
create table if not exists public.market_members (market_id uuid references public.markets(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, role text not null default 'manager', primary key(market_id,user_id));
create table if not exists public.products (id uuid primary key default uuid_generate_v4(), market_id uuid not null references public.markets(id), name text not null check (char_length(name) between 1 and 160), sku text not null, category text not null, stock integer not null default 0 check(stock >= 0), cost_price numeric(12,2) not null check(cost_price >= 0), sale_price numeric(12,2) not null check(sale_price >= 0), created_at timestamptz default now(), unique(market_id,sku));
create table if not exists public.sales (id uuid primary key default uuid_generate_v4(), market_id uuid not null references public.markets(id), product_id uuid not null references public.products(id), quantity integer not null check(quantity > 0), unit_cost numeric(12,2) not null, unit_price numeric(12,2) not null, revenue numeric(12,2) generated always as (quantity * unit_price) stored, cogs numeric(12,2) generated always as (quantity * unit_cost) stored, profit numeric(12,2) generated always as (quantity * (unit_price-unit_cost)) stored, sold_at timestamptz default now(), created_by uuid references auth.users(id));
alter table public.products enable row level security; alter table public.sales enable row level security; alter table public.market_members enable row level security;
create or replace function public.is_market_member(mid uuid) returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from market_members where market_id=mid and user_id=auth.uid()) $$;
create policy "members read products" on public.products for select using (is_market_member(market_id)); create policy "members insert products" on public.products for insert with check (is_market_member(market_id)); create policy "members update products" on public.products for update using (is_market_member(market_id));
create policy "members read sales" on public.sales for select using (is_market_member(market_id)); create policy "members insert sales" on public.sales for insert with check (is_market_member(market_id));
create or replace function public.register_sale(p_product_id uuid,p_quantity integer) returns public.sales language plpgsql security definer set search_path=public as $$ declare p products; s sales; begin if p_quantity <= 0 then raise exception 'quantity must be positive'; end if; select * into p from products where id=p_product_id for update; if p is null or p.stock < p_quantity then raise exception 'insufficient stock'; end if; update products set stock=stock-p_quantity where id=p_product_id; insert into sales(market_id,product_id,quantity,unit_cost,unit_price,created_by) values(p.market_id,p.id,p_quantity,p.cost_price,p.sale_price,auth.uid()) returning * into s; return s; end $$;
